<script setup lang="ts">
import { computed, ref, watch } from 'vue';
import { route as routeSource, go, setQuery, back } from '../workbench/navigation';
import { learningSpaces, spaceChapters, spaceRequirements, spaceClaims, spaceEvidence, lastActivity, requirementIssues, assessmentFor, courseKnowledge, adoptedDefinitions, type MockLearningSpace } from '../workbench/learning-space-mock';
import WorkbenchDialog from './WorkbenchDialog.vue';
const route=routeSource,location=window.location;
const space=computed(()=>learningSpaces.find(s=>s.id===route.id));
const tabs={overview:'概览',course:'课程范围',requirements:'学习要求与状态',records:'学习记录'};
const tab=computed(()=>Object.prototype.hasOwnProperty.call(tabs,route.tab)?route.tab:'overview');
const list=computed(()=>learningSpaces.filter(s=>(!route.filter||s.adopted.book.id===route.filter)&&(!route.claim||s.adopted.target.id===route.claim)&&(!route.status||(route.status==='active'?s.activities.length>0:s.activities.length===0))&&`${s.id} ${s.name} ${s.studentId} ${s.studentName}`.toLowerCase().includes(route.q.trim().toLowerCase())));
const pages=computed(()=>Math.max(1,Math.ceil(list.value.length/10))),page=computed(()=>Math.min(route.p,pages.value));
const books=computed(()=>[...new Map(learningSpaces.map(s=>[s.adopted.book.id,s.adopted.book])).values()]);
const targets=computed(()=>[...new Map(learningSpaces.map(s=>[s.adopted.target.id,s.adopted.target])).values()]);
const chapters=computed(()=>space.value?spaceChapters(space.value):[]);
const filteredChapters=computed(()=>chapters.value.filter(ch=>ch.name.includes(route.q.trim())));
const chapter=computed(()=>chapters.value.find(ch=>ch.id===route.chapter)||(route.chapter?undefined:filteredChapters.value[0]));
const requirements=computed(()=>space.value?spaceRequirements(space.value):[]);
const claims=computed(()=>space.value?spaceClaims(space.value):[]);
const claim=computed(()=>claims.value.find(c=>c.id===route.claim));
const filteredClaims=computed(()=>claims.value.filter(c=>(!route.chapter||requirements.value.some(r=>r.claim?.id===c.id&&r.requirement.chapterIds.includes(route.chapter)))&&(c.name+' '+taskName(c.taskId)).includes(route.q.trim())));
const definitions=computed(()=>space.value?adoptedDefinitions(space.value):[]);
const changed=computed(()=>definitions.value.filter(d=>d.changed));
const records=computed(()=>space.value?.activities.filter(a=>(!route.chapter||a.chapterId===route.chapter)&&(a.name+' '+a.id).includes(route.q.trim()))||[]);
const recordPages=computed(()=>Math.max(1,Math.ceil(records.value.length/10))),recordPage=computed(()=>Math.min(route.p,recordPages.value));
const stateLabel=(s:MockLearningSpace)=>s.activities.length?'已有学习记录':'尚无学习记录';
const taskName=(id:string)=>space.value?.adopted.domain.tasks.find(t=>t.id===id)?.name||id;
const methodName=(id:string)=>space.value?.adopted.domain.methods.find(m=>m.id===id)?.name||id;
const chapterName=(id:string)=>space.value?.adopted.book.units.flatMap(u=>u.chapters).find(ch=>ch.id===id)?.name||id;
const claimRequirements=(id:string)=>requirements.value.filter(r=>r.selection.claimId===id);
const counts=(s:MockLearningSpace,claimId='',chapterId='')=>spaceRequirements(s).filter(r=>(!claimId||r.selection.claimId===claimId)&&(!chapterId||r.requirement.chapterIds.includes(chapterId))).reduce((sum,r)=>{sum[assessmentFor(s,r.requirement.id).status]++;return sum;},{已达标:0,需加强:0,待确认:0});
const pending=computed(()=>requirements.value.filter(r=>requirementIssues(space.value!,r.requirement.id).length).length);
const chapterTasks=computed(()=>[...new Set(chapters.value.flatMap(ch=>ch.mappings.map(m=>m.taskId)))]);
const roots=computed(()=>[...new Set(chapters.value.flatMap(ch=>ch.mappings.flatMap(m=>m.methods)))]);
const knowledge=computed(()=>space.value?courseKnowledge(space.value,chapter.value?.mappings.flatMap(m=>m.methods)||[]):{rows:[],methods:[],issues:[]});
const missingTargets=computed(()=>chapters.value.filter(ch=>!requirements.value.some(r=>r.requirement.chapterIds.includes(ch.id))));
const snapshotOpen=ref(false),modal=ref<'requirement'|'activity'|'definition'|null>(null),modalId=ref(''),returnRequirement=ref('');
const requirement=computed(()=>requirements.value.find(r=>r.requirement.id===modalId.value));
const activity=computed(()=>space.value?.activities.find(a=>a.id===modalId.value));
const definition=computed(()=>definitions.value.find(d=>d.id===modalId.value));
const snapshotFields=computed(()=>{
  if(!definition.value||!space.value)return [];
  const {id,kind}=definition.value,b=space.value.adopted;
  if(kind==='教材')return [['教材',b.book.name],['版次',b.book.edition],['适用范围',b.book.grade+' · '+b.book.subject],['来源',b.book.sourceNote],['已选章节',chapters.value.map(ch=>ch.name).join('、')]];
  if(kind==='学习目标')return [['目标',b.target.name],['说明',b.target.description],['目标章节',b.target.chapterIds.map(chapterName).join('、')],['当前空间适用要求',requirements.value.map(r=>r.requirement.name).join('\n')]];
  if(kind==='Task Claim'){const c=b.claims.find(c=>c.id===id)!;return [['Task',taskName(c.taskId)],['任务范围',c.scope],['完成责任',c.responsibility],['方法条件',(c.methodMode==='all'?'分别覆盖全部：':'任选一种：')+c.methods.map(methodName).join('、')],['支持边界',c.support],['评价方面',c.aspects.map(a=>a.name+'：'+(a.applicable?a.criterion:'不适用；'+a.reason)).join('\n')]];}
  if(kind==='Task'){const t=b.domain.tasks.find(t=>t.id===id)!;return [['任务目标',t.goal],['完成责任',t.responsibility],['预期输出',t.output],['允许的变化',t.variations],['适用边界',t.exclusions]];}
  if(kind==='Solution'){const m=b.domain.methods.find(m=>m.id===id)!;return [['说明',m.description],['适用条件',m.conditions],['输出',m.output],['步骤',m.steps.map((step,i)=>(i+1)+'. '+step.title+'：'+step.detail+(step.solutionId?'（子方法：'+methodName(step.solutionId)+'）':'')).join('\n')],['直接关联 KC',m.kc.map(id=>b.domain.knowledge.find(k=>k.id===id)?.name||id).join('、')]];}
  const k=b.domain.knowledge.find(k=>k.id===id)!;return [['知识说明',k.description],['知识前置依赖',k.prerequisites.map(id=>b.domain.knowledge.find(k=>k.id===id)?.name||id).join('、')||'未配置']];
});
const selectedRequirements=computed(()=>requirements.value.filter(r=>(!route.claim||r.selection.claimId===route.claim)&&(!route.chapter||r.requirement.chapterIds.includes(route.chapter))));
watch(()=>route.id,()=>{modal.value=null;snapshotOpen.value=false;});
function openSpace(id:string){go('learning-spaces',{id,returnTo:location.hash});}
function selectTab(value:string){setQuery({tab:value,chapter:'',claim:'',q:'',p:1});}
function openBook(id=''){go('textbooks',{id:space.value!.adopted.book.id,chapter:id,tab:id?'mapping':'',returnTo:location.hash});}
function openTarget(id=''){go('targets',{id:space.value!.adopted.target.id,claim:id,returnTo:location.hash});}
function openClaim(id:string){go('evaluation',{id,tab:'definition',returnTo:location.hash});}
function openDomain(kind:string,id:string){go('domain',{domain:space.value!.adopted.book.domainId,filter:kind,id,returnTo:location.hash});}
function showRequirement(id:string){modalId.value=id;modal.value='requirement';returnRequirement.value='';}
function openReview(id:string){modal.value=null;go('activity',{id,returnTo:location.hash});}
function showActivity(id:string){returnRequirement.value=modal.value==='requirement'?modalId.value:'';modalId.value=id;modal.value='activity';}
function showDefinition(id:string){modalId.value=id;modal.value='definition';}
function currentDefinition(){
  const d=definition.value;if(!d)return;modal.value=null;
  if(d.kind==='教材')openBook();else if(d.kind==='学习目标')openTarget();else if(d.kind==='Task Claim')openClaim(d.id);else openDomain(({Task:'task',Solution:'solution',KC:'kc'} as Record<string,string>)[d.kind]!,d.id);
}
</script>
<template><div class="wb-page learning-space-workspace">
  <template v-if="!route.id">
    <header class="page-header"><div><h2>学习空间管理</h2><p class="page-desc">查看学生选择的课程范围、学习目标及个人学习情况。</p></div></header>
    <div class="toolbar space-filters"><label class="search-label">搜索学习空间<input type="search" :value="route.q" placeholder="学生、空间名称或编号" @input="setQuery({q:($event.target as HTMLInputElement).value,p:1})"/></label><label>教材<select :value="route.filter" aria-label="筛选教材" @change="setQuery({filter:($event.target as HTMLSelectElement).value,p:1})"><option value="">全部教材</option><option v-for="b in books" :key="b.id" :value="b.id">{{b.name}}</option></select></label><label>学习目标<select :value="route.claim" aria-label="筛选学习目标" @change="setQuery({claim:($event.target as HTMLSelectElement).value,p:1})"><option value="">全部目标</option><option v-for="t in targets" :key="t.id" :value="t.id">{{t.name}}</option></select></label><label>学习记录<select :value="route.status" aria-label="筛选学习记录" @change="setQuery({status:($event.target as HTMLSelectElement).value,p:1})"><option value="">全部</option><option value="active">已有学习记录</option><option value="empty">尚无学习记录</option></select></label></div>
    <p class="list-summary">{{list.length}} 个空间 · {{new Set(list.map(s=>s.studentId)).size}} 位学生<span>空间由学生创建；下列数据均为交互示例。</span></p>
    <section class="table-card"><table class="data-table space-list"><thead><tr><th>学生 / 学习空间</th><th>教材与目标</th><th>学习范围</th><th>学习记录</th><th>最近活动</th></tr></thead><tbody><tr v-for="s in list.slice((page-1)*10,page*10)" :key="s.id"><td><button class="text-link item-name" :aria-label="'查看 '+s.studentName+'的'+s.name" @click="openSpace(s.id)">{{s.name}}</button><small>{{s.studentName}} · {{s.studentId}}</small><small>{{s.id}}</small></td><td>{{s.adopted.book.name}}<small>{{s.adopted.target.name}}</small></td><td>{{s.chapterIds.length}} 个章节<small>{{spaceRequirements(s).length}} 项学习要求</small></td><td><span class="badge" :class="s.activities.length?'green':''">{{stateLabel(s)}}</span><small>{{s.activities.length}} 次活动 · {{spaceEvidence(s).length}} 条 Evidence</small></td><td>{{lastActivity(s)||'—'}}</td></tr></tbody></table><p v-if="!list.length" class="empty">没有符合条件的空间。请调整搜索或筛选。</p></section>
    <div v-if="pages>1" class="pagination"><button class="btn" :disabled="page<=1" @click="setQuery({p:page-1})">上一页</button><span>{{page}} / {{pages}}</span><button class="btn" :disabled="page>=pages" @click="setQuery({p:page+1})">下一页</button></div>
  </template>
  <template v-else-if="space">
    <header class="page-header space-header"><div><button class="text-link" @click="back('learning-spaces')">← {{route.returnTo.startsWith('#/users')?'返回用户管理':route.returnTo.startsWith('#/students')?'返回学生状态':route.returnTo.startsWith('#/objects')?'返回空间观测':route.returnTo.startsWith('#/activity')||route.returnTo.startsWith('#/trace-list')?'返回交互审查':'返回空间列表'}}</button><h2>{{space.name}} <span class="badge">{{stateLabel(space)}}</span></h2><p class="page-desc">{{space.studentName}} · {{space.studentId}} · {{space.id}}<span class="header-divider">创建于 {{space.createdAt}}</span></p><div class="adoption-context"><span>{{space.adopted.book.name}} · v{{space.adopted.book.revision}}</span><span>{{space.adopted.target.name}} · v{{space.adopted.target.revision}}</span></div></div><div class="button-row"><button class="btn" @click="go('students',{id:space.studentId,scope:space.id,returnTo:location.hash})">学生状态 →</button><button class="btn" @click="snapshotOpen=!snapshotOpen">{{snapshotOpen?'收起版本追溯':'采用版本与历史'}}<span v-if="changed.length" class="badge amber">{{changed.length}} 项有变化</span></button></div></header>
    <p v-if="changed.length" class="callout amber adoption-warning">管理目录已有 {{changed.length}} 项内容变化。本空间仍显示原采用内容与个人记录，尚未更新采用。</p>
    <section v-if="snapshotOpen" class="panel version-panel"><h3>采用版本与历史</h3><p class="muted">教材、目标与 Claim 使用各自版本；Task／Solution／KC 暂保留初始内容快照，不虚构版本编号。清单仅列本空间关联定义。</p><div class="version-table-wrap"><table class="data-table version-table"><thead><tr><th>对象</th><th>类型</th><th>已采用</th><th>管理目录</th><th></th></tr></thead><tbody><tr v-for="d in definitions" :key="d.kind+d.id"><td>{{d.name}}<small>{{d.id}}</small></td><td>{{d.kind}}</td><td>{{d.version}}</td><td>{{d.current?d.currentVersion:'当前定义已不存在'}}<small :class="{changed:d.changed}">{{d.changed?'内容有变化，未采用':'与采用内容一致'}}</small></td><td><button class="text-link" :aria-label="'查看采用快照 '+d.name" @click="showDefinition(d.id)">查看快照</button></td></tr></tbody></table></div><div v-for="(h,i) in space.history" :key="i" class="list-row"><div>{{h.description}}<small>{{h.actor}} · {{h.at}}</small></div></div><p class="muted">这里只查看采用与追溯；教材和目标由管理员在所属页面应用更新；学生不维护版本或长期章节范围。</p></section>
    <div class="tabs" role="tablist" aria-label="学习空间详情"><button v-for="(label,key) in tabs" :key="key" role="tab" :aria-selected="tab===key" :class="{active:tab===key}" @click="selectTab(key)">{{label}}</button></div>
    <template v-if="tab==='overview'">
      <div class="two-columns"><section class="panel"><h3>课程采用</h3><dl class="field-list"><dt>教材</dt><dd>{{space.adopted.book.name}} · v{{space.adopted.book.revision}}<button class="text-link owner-link" @click="openBook()">查看教材当前定义 ↗</button></dd><dt>学习目标</dt><dd>{{space.adopted.target.name}} · v{{space.adopted.target.revision}}<button class="text-link owner-link" @click="openTarget()">查看目标当前定义 ↗</button></dd><dt>课程内容范围</dt><dd>{{chapters.length}} 个章节 · {{chapterTasks.length}} 项 Task · {{roots.length}} 个直接方法<button class="text-link owner-link" @click="selectTab('course')">查看课程范围 →</button></dd><dt>课堂进度</dt><dd>{{space.classroom?space.classroom.chapterIds.map(chapterName).join('、'):'学生尚未确认'}}<small v-if="space.classroom">学生报告 · {{space.classroom.confirmedAt}}</small><small>仅表示课堂正在学什么，不表示已掌握。</small></dd></dl></section>
      <section class="panel personal-summary"><h3>学习要求的当前结果 <span class="badge">预写示例</span></h3><div class="result-counts"><div v-for="(count,status) in counts(space)" :key="status"><strong>{{count}}</strong><span>{{status}}</span></div></div><p class="muted">共 {{requirements.length}} 项目标要求；按实际要求计数，不把 Claim 数量乘以四，也不计算平均掌握率。</p><p v-if="!space.judgments.length" class="callout">尚未形成此空间的个人判断。不代表未掌握，也不从其他空间复制状态。</p><p v-else>{{space.id.startsWith('FLOW-SPACE-')?'已有本轮作答记录；mock 判断和正式能力结论分开，当前要求仍待确认。':'已有记录支持部分常规计算；解释不足、迁移与延迟保持分别保留判断。'}}</p><button class="text-link" @click="selectTab('requirements')">查看具体要求与个人状态 →</button><details v-if="pending||missingTargets.length"><summary>查看课程准备缺口</summary><p v-if="pending">{{pending}} 项要求的方法或适用条件待核对。它们保持待确认，不计作学生能力不足。</p><p v-if="missingTargets.length">{{missingTargets.map(ch=>ch.name).join('、')}}：本目标尚未配置相应学习要求，不计入达标统计；不因此一律拒绝讲解。</p></details></section></div>
      <section class="panel"><div class="section-heading"><h3>近期学习</h3><button class="text-link" @click="selectTab('records')">全部学习记录 →</button></div><div v-for="a in space.activities.slice(0,3)" :key="a.id" class="list-row"><div><button class="text-link" @click="showActivity(a.id)">{{a.name}}</button><small>{{chapterName(a.chapterId)}} · {{a.kind}}</small></div><span class="muted">{{a.at}}</span></div><p v-if="!space.activities.length" class="empty">此空间尚无学习记录。</p></section>
    </template>
    <template v-else-if="tab==='course'">
      <div class="course-layout"><aside class="panel chapter-nav"><h3>教材章节</h3><label>查找章节<input type="search" :value="route.q" @input="setQuery({q:($event.target as HTMLInputElement).value,chapter:''})"/></label><template v-for="u in space.adopted.book.units" :key="u.id"><h4 v-if="u.chapters.some(ch=>filteredChapters.some(c=>c.id===ch.id))">{{u.name}}</h4><button v-for="ch in u.chapters.filter(ch=>filteredChapters.some(c=>c.id===ch.id))" :key="ch.id" class="chapter-button" :class="{selected:chapter?.id===ch.id}" @click="setQuery({chapter:ch.id})">{{ch.name}}<small v-if="space.classroom?.chapterIds.includes(ch.id)">课堂正在学</small></button></template><p v-if="!filteredChapters.length" class="empty">没有匹配章节。</p></aside>
      <div v-if="chapter" class="course-content"><section class="panel"><div class="section-heading"><h3>{{chapter.name}}</h3><button class="text-link" @click="openBook(chapter.id)">查看教材当前映射 ↗</button></div><p>{{chapter.content||'本章内容尚未整理。'}}</p><p class="muted">以下采用内容来自教材 v{{space.adopted.book.revision}}；Task 只列本章直接采用的方法，子方法在 Solution 内查看。对象链接打开管理目录中的当前定义。</p><table class="data-table course-mappings"><thead><tr><th>Task</th><th>本章采用的直接 Solution</th><th>目标中的 Task Claim</th></tr></thead><tbody><tr v-for="m in chapter.mappings" :key="m.id"><td><button class="text-link" @click="openDomain('task',m.taskId)">{{taskName(m.taskId)}} ↗</button></td><td><button v-for="id in m.methods" :key="id" class="text-link owner-link" @click="openDomain('solution',id)">{{methodName(id)}} ↗</button><span v-if="!m.methods.length">尚未关联方法</span></td><td><button v-for="c in claims.filter(c=>c.taskId===m.taskId&&claimRequirements(c.id).some(r=>r.requirement.chapterIds.includes(chapter!.id)))" :key="c.id" class="text-link owner-link" @click="setQuery({tab:'requirements',claim:c.id,chapter:'',q:''})">{{c.name}} →</button><span v-if="!claims.some(c=>c.taskId===m.taskId&&claimRequirements(c.id).some(r=>r.requirement.chapterIds.includes(chapter!.id)))">本章未纳入目标要求</span></td></tr></tbody></table><p v-if="!chapter.mappings.length" class="empty">尚无 Task／Solution 映射。内容准备缺口不代表学生未掌握。</p></section>
      <section class="panel"><h3>关联知识 <span class="badge">{{knowledge.rows.length}} 项 KC</span></h3><p class="muted">只从本章采用的 Solution 及其子方法递归汇总并去重，不从 Task 直接关联，也不表示学生已掌握这些知识。</p><table class="data-table course-knowledge"><thead><tr><th>Knowledge Component</th><th>来源方法（含递归引用）</th></tr></thead><tbody><tr v-for="k in knowledge.rows" :key="k.id"><td><button class="text-link" @click="openDomain('kc',k.id)">{{k.name}} ↗</button></td><td>{{[...k.roots].map(methodName).join('、')}}</td></tr></tbody></table><p v-if="!knowledge.rows.length" class="empty">暂无可汇总的知识依据。</p><p v-if="knowledge.issues.length" class="callout amber">{{knowledge.issues.join('；')}}</p></section></div><p v-else class="empty">请选择当前空间中的章节。</p></div>
    </template>
    <template v-else-if="tab==='requirements'">
      <p class="muted">目标要求决定“需要达到什么”；个人 Belief 描述“当前有什么依据”。下列个人判断和达标结果均为预写示例。</p>
      <template v-if="!route.claim"><div class="toolbar"><label class="search-label">查找 Claim<input type="search" :value="route.q" placeholder="Claim 或任务名称" @input="setQuery({q:($event.target as HTMLInputElement).value})"/></label><label>教材章节<select aria-label="筛选要求章节" :value="route.chapter" @change="setQuery({chapter:($event.target as HTMLSelectElement).value})"><option value="">全部教材章节</option><option v-for="ch in chapters" :key="ch.id" :value="ch.id">{{ch.name}}</option></select></label></div><section class="table-card"><table class="data-table space-claims"><thead><tr><th>Task Claim / Task</th><th>具体学习要求</th><th>目标结果（项）</th><th>配置情况</th></tr></thead><tbody><tr v-for="c in filteredClaims" :key="c.id"><td><button class="text-link item-name" @click="setQuery({claim:c.id,q:''})">{{c.name}}</button><small>{{taskName(c.taskId)}}</small></td><td>{{claimRequirements(c.id).filter(r=>!route.chapter||r.requirement.chapterIds.includes(route.chapter)).length}} 项<small>{{[...new Set(claimRequirements(c.id).flatMap(r=>r.requirement.chapterIds))].map(chapterName).join('、')}}</small></td><td><span v-for="(count,status) in counts(space,c.id,route.chapter)" :key="status" class="count-label">{{status}} {{count}}</span></td><td><span class="badge" :class="claimRequirements(c.id).some(r=>requirementIssues(space!,r.requirement.id).length)?'amber':'green'">{{claimRequirements(c.id).some(r=>requirementIssues(space!,r.requirement.id).length)?'适用条件待核对':'要求已配置'}}</span></td></tr></tbody></table><p v-if="!filteredClaims.length" class="empty">{{route.q?'没有匹配的 Claim。':'所选范围尚无目标学习要求；不把内容缺口计为学生未掌握。'}}</p></section></template>
      <template v-else-if="claim"><button class="text-link claim-back" @click="setQuery({claim:''})">← 返回 Claim 列表</button><section class="panel claim-context"><div class="section-heading"><h3>{{claim.name}} <span class="badge">采用 v{{claim.version}}</span></h3><button class="text-link" @click="openClaim(claim.id)">查看 Claim 当前定义 ↗</button></div><p>{{taskName(claim.taskId)}}</p><p class="method-policy">方法条件：{{claim.methodMode==='all'?'分别覆盖全部方法':'可任选一种方法'}} · {{claim.methods.map(methodName).join('、')}}</p><details><summary>支持边界与目标来源</summary><p>{{claim.support}}</p><p>{{claim.methodNote}}</p><button class="text-link" @click="openTarget(claim.id)">查看目标当前要求 ↗</button></details></section>
      <section class="table-card"><table class="data-table space-requirements"><thead><tr><th>学习要求 / 评价方面</th><th>达标结果</th><th>判断说明</th><th></th></tr></thead><tbody><tr v-for="r in selectedRequirements" :key="r.requirement.id"><td>{{r.requirement.name}}<small>{{r.requirement.aspectIds.map(id=>claim!.aspects.find(a=>a.id===id)?.name||id).join('、')}}</small></td><td><span class="badge" :class="assessmentFor(space,r.requirement.id).status==='已达标'?'green':assessmentFor(space,r.requirement.id).status==='需加强'?'red':''">{{assessmentFor(space,r.requirement.id).status}}</span></td><td>{{assessmentFor(space,r.requirement.id).reason}}<small v-if="requirementIssues(space,r.requirement.id).length" class="condition-warning">{{requirementIssues(space,r.requirement.id).join('；')}}</small></td><td><button class="text-link" :aria-label="'查看要求 '+r.requirement.name" @click="showRequirement(r.requirement.id)">标准与依据</button></td></tr></tbody></table></section>
      <details class="belief-details"><summary>查看本 Claim 的个人 Belief（含未纳入目标的方面）</summary><table class="data-table personal-beliefs"><thead><tr><th>评价方面</th><th>个人判断</th><th>适用条件与不确定性</th></tr></thead><tbody><tr v-for="a in claim.aspects" :key="a.id"><td>{{a.name}}<small v-if="!a.applicable">定义为不适用：{{a.reason}}</small></td><td>{{space.judgments.find(j=>j.claimId===claim!.id&&j.aspectId===a.id)?.judgment||(a.applicable?'尚未形成判断':'不作评价')}}</td><td>{{space.judgments.find(j=>j.claimId===claim!.id&&j.aspectId===a.id)?.uncertainty||a.criterion}}<small v-if="a.applicable&&!space.judgments.some(j=>j.claimId===claim!.id&&j.aspectId===a.id)">没有相应表现依据，不用其他方面补齐。</small></td></tr></tbody></table></details></template>
      <p v-else class="empty">此 Claim 未纳入当前空间的学习要求。<button class="text-link" @click="setQuery({claim:''})">返回列表</button></p>
    </template>
    <template v-else-if="tab==='records'"><div class="toolbar"><label class="search-label">查找学习记录<input type="search" :value="route.q" placeholder="活动名称或编号" @input="setQuery({q:($event.target as HTMLInputElement).value,p:1})"/></label><label>教材章节<select aria-label="筛选记录章节" :value="route.chapter" @change="setQuery({chapter:($event.target as HTMLSelectElement).value,p:1})"><option value="">全部教材章节</option><option v-for="ch in chapters" :key="ch.id" :value="ch.id">{{ch.name}}</option></select></label><span class="muted">{{records.length}} 次活动 · {{records.reduce((n,a)=>n+a.evidence.length,0)}} 条 Evidence</span></div><section class="table-card"><table class="data-table space-records"><thead><tr><th>活动 / 章节</th><th>时间</th><th>实际帮助</th><th>Evidence</th><th></th></tr></thead><tbody><tr v-for="a in records.slice((recordPage-1)*10,recordPage*10)" :key="a.id"><td>{{a.name}}<small>{{chapterName(a.chapterId)}} · {{a.kind}}</small></td><td>{{a.at}}</td><td>{{a.help}}</td><td>{{a.evidence.length}} 条</td><td><button class="text-link" :aria-label="'查看记录 '+a.name" @click="showActivity(a.id)">记录与依据</button><button class="text-link owner-link" :aria-label="'审查活动 '+a.name" @click="openReview(a.id)">交互审查 →</button></td></tr></tbody></table><p v-if="!records.length" class="empty">{{route.q||route.chapter?'没有符合筛选条件的记录。':'此空间尚无学习记录，不借用其他空间的活动或判断。'}}</p></section><div v-if="recordPages>1" class="pagination"><button class="btn" :disabled="recordPage<=1" @click="setQuery({p:recordPage-1})">上一页</button><span>{{recordPage}} / {{recordPages}}</span><button class="btn" :disabled="recordPage>=recordPages" @click="setQuery({p:recordPage+1})">下一页</button></div></template>
    <WorkbenchDialog v-if="modal" :key="modal" :title="modal==='requirement'?'学习要求与个人依据':modal==='activity'?'学习记录与 Evidence':'已采用的定义快照'" wide @close="modal=null">
      <template v-if="modal==='requirement'&&requirement"><h3>{{requirement.requirement.name}}</h3><dl class="field-list"><dt>所属章节</dt><dd>{{requirement.requirement.chapterIds.map(chapterName).join('、')}}</dd><dt>达标标准</dt><dd>{{requirement.requirement.standard}}</dd><dt>当前目标结果</dt><dd>{{assessmentFor(space,requirement.requirement.id).status}}<small>{{assessmentFor(space,requirement.requirement.id).reason}}</small></dd></dl><p v-for="issue in requirementIssues(space,requirement.requirement.id)" :key="issue" class="callout amber">{{issue}}</p><section v-for="id in requirement.requirement.aspectIds" :key="id" class="panel"><h4>{{requirement.claim?.aspects.find(a=>a.id===id)?.name||id}} · 个人 Belief</h4><p>{{space.judgments.find(j=>j.claimId===requirement!.selection.claimId&&j.aspectId===id)?.judgment||'尚未形成判断'}}</p><p class="muted">{{space.judgments.find(j=>j.claimId===requirement!.selection.claimId&&j.aspectId===id)?.uncertainty||requirement.claim?.aspects.find(a=>a.id===id)?.criterion}}</p><div v-for="e in spaceEvidence(space).filter(e=>e.claimId===requirement!.selection.claimId&&e.aspectId===id)" :key="e.id" class="list-row"><div><p>{{e.meaning}}</p><button class="text-link" @click="showActivity(e.activity.id)">查看原始记录 · {{e.activity.name}} →</button><small>{{e.id}} · {{e.activity.at}}</small></div></div><p v-if="!spaceEvidence(space).some(e=>e.claimId===requirement!.selection.claimId&&e.aspectId===id)" class="muted">暂无本空间的相应 Evidence。未检测不等于未掌握。</p></section></template>
      <template v-else-if="modal==='activity'&&activity"><button v-if="returnRequirement" class="text-link" @click="showRequirement(returnRequirement)">← 返回学习要求</button><h3>{{activity.name}}</h3><p class="muted">{{space.studentName}} · {{space.name}} · {{activity.at}} · 预写交互记录</p><p class="callout">实际帮助：{{activity.help}}</p><div v-for="(m,i) in activity.messages" :key="i" class="audit-turn" :class="{user:m.actor==='学生'}"><header>{{m.actor}}</header><p>{{m.text}}</p></div><h4>Evidence 解释</h4><div v-for="e in activity.evidence" :key="e.id" class="list-row"><div><p>{{e.meaning}}</p><small>{{e.id}} · {{space.adopted.claims.find(c=>c.id===e.claimId)?.name}} / {{space.adopted.claims.find(c=>c.id===e.claimId)?.aspects.find(a=>a.id===e.aspectId)?.name}}</small></div></div><p class="muted">本记录仅属于 {{space.id}}；多条 Evidence 不代表多次独立作答。</p><div class="dialog-footer"><button class="btn" @click="openReview(activity.id)">进入交互审查 →</button></div></template>
      <template v-else-if="modal==='definition'&&definition"><h3>{{definition.name}}</h3><p>{{definition.kind}} · {{definition.id}} · {{definition.version}}</p><p v-if="definition.changed" class="callout amber">管理目录内容已经变化；以下仍是本空间原采用内容。</p><dl class="field-list snapshot-fields"><template v-for="(f,i) in snapshotFields" :key="i"><dt>{{f[0]}}</dt><dd>{{f[1]||'未填写'}}</dd></template></dl><details><summary>查看原始字段</summary><pre>{{JSON.stringify(definition.value,null,2)}}</pre></details><button v-if="definition.current" class="btn" @click="currentDefinition">查看当前定义 ↗</button><p class="muted">打开管理页面会显示当前定义；返回空间后仍按原采用快照查看，不会自动更新。</p></template>
    </WorkbenchDialog>
  </template>
  <section v-else class="panel"><h2>未找到这个学习空间</h2><p>请返回列表选择当前交互示例，不将未知编号绑定到其他学生的空间。</p><button class="btn" @click="go('learning-spaces')">返回空间列表</button></section>
</div></template>
