child{width:32%}.space-claims th:nth-child(2){width:25%}.space-claims th:nth-child(3){width:18%}.space-requirements th:first-child{width:29%}.space-requirements th:nth-child(2){width:90px}.space-requirements th:last-child{width:112px}.space-requirements td:last-child .text-link{white-space:nowrap}.claim-back{margin:16px 0}.method-policy{font-size:13px;color:#4b6956}.condition-warning,.changed{color:#9b7129!important}.version-table-wrap{max-height:420px;overflow:auto}.version-table th{position:sticky;top:0}.version-table th:first-child{width:35%}.version-table th:last-child{width:90px}.space-records th:first-child{width:27%}.space-records th:nth-child(2){width:140px}.space-records th:nth-child(4){width:75px}.space-records th:last-child{width:90px}.belief-details{margin-bottom:28px}.personal-beliefs th:first-child{width:16%}.personal-beliefs th:nth-child(2){width:30%}@media(max-width:1100px){.course-layout{grid-template-columns:190px minmax(0,1fr);gap:12px}.course-content .panel{padding:14px}.space-header{flex-wrap:wrap}.header-divider{display:block;margin:4px 0 0}.list-summary span{display:block;margin:4px 0}.space-filters select{max-width:none}}
